function followUpHint() {
  const example = "for example: 2026-09-14 09:30";
  if (channel === "telegram") {
    return "Reply in this chat with the exact date and time you want (" + example + ").";
  }
  if (channel === "email") {
    return "Reply to this email with the exact date and time you want (" + example + ").";
  }
  return "Do not reply to this email. Open the website form again, use the SAME email address, and submit a new message with the exact date and time you want (" + example + ").";
}

