  ];
}

const reqStart = requested.getTime();
const reqEnd = reqStart + durationMin * 60000;
const free = isBusiness(requested) && !overlaps(reqStart, reqEnd);

if (free) {
  const startIso = toIsoLocal(requested);
  const endIso = toIsoLocal(new Date(reqEnd));
  return [
